import React, { useState } from "react";
import { Container, Row, Col, Form, Button } from "react-bootstrap";
import {
  FaPhone,
  FaEnvelope,
  FaMapMarkerAlt,
  FaFacebookF,
  FaTwitter,
  FaInstagram,
  FaWhatsapp,
  FaPaperPlane,
} from "react-icons/fa";
import "./ContactForm.css";

export default function ContactForm() {
  const [status, setStatus] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setStatus("");

    const formData = new FormData(e.target);

    try {
      const response = await fetch(
        "https://script.google.com/macros/s/AKfycby5cPC20OWrwY-6hRwJgRN3uXQEaftlXoPc6B59RHfKI0-yDC-YYPQ9SZV78MVOG812/exec",
        { method: "POST", body: formData }
      );

      if (response.ok) {
        setStatus("✅ Message sent successfully!");
        e.target.reset();
      } else {
        setStatus("❌ Failed to send message. Try again later.");
      }
    } catch (error) {
      setStatus("⚠️ Error: " + error.message);
    } finally {
      setIsSubmitting(false);
      setTimeout(() => setStatus(""), 4000);
    }
  };

  return (
    <Container className="contact-container py-5">
      <Row className="justify-content-center">
        <Col lg={10}>
          <h1 className="text-center mb-4 fw-bold">Contact Us</h1>
          <p className="text-center mb-5 text-muted">
            Any question or remarks? Just write us a message!
          </p>

          <div className="contact-wrapper d-lg-flex shadow-lg rounded-4 overflow-hidden">
            {/* Left Info Section */}
            <div className="contact-info p-4 p-lg-5 text-white">
              <h2>Contact Information</h2>
              <p className="mb-4">
                Fill up the form and our team will get back to you within 24 hours.
              </p>

              <ul className="list-unstyled">
                <li className="mb-3">
                  <FaPhone className="me-2" /> +91 7558004898
                </li>
                <li className="mb-3">
                  <FaEnvelope className="me-2" /> kidtivitybox@gmail.com
                </li>
                <li>
                  <FaMapMarkerAlt className="me-2" /> Kadakaserry, Kuttipuram Road,
                  Malapuram, 679573
                </li>
              </ul>

              {/* Social Icons */}
              <div className="d-flex gap-3 mt-4">
                <a href="https://facebook.com" className="social-btn" target="_blank" rel="noreferrer">
                  <FaFacebookF />
                </a>
                <a href="https://twitter.com" className="social-btn" target="_blank" rel="noreferrer">
                  <FaTwitter />
                </a>
                <a href="https://instagram.com/kidtivity.in" className="social-btn" target="_blank" rel="noreferrer">
                  <FaInstagram />
                </a>
                <a
                  href="https://chat.whatsapp.com/EF7EZfWWglvGdNbhPoROiI"
                  className="social-btn"
                  target="_blank"
                  rel="noreferrer"
                >
                  <FaWhatsapp />
                </a>
              </div>
            </div>

            {/* Right Form Section */}
            <Form className="contact-form flex-fill p-4 p-lg-5" onSubmit={handleSubmit}>
              <Row className="mb-3">
                <Col md={6}>
                  <Form.Floating className="mb-3">
                    <Form.Control type="text" name="firstName" placeholder="First Name" required />
                    <label>First Name</label>
                  </Form.Floating>
                </Col>
                <Col md={6}>
                  <Form.Floating className="mb-3">
                    <Form.Control type="text" name="lastName" placeholder="Last Name" required />
                    <label>Last Name</label>
                  </Form.Floating>
                </Col>
              </Row>

              <Row className="mb-3">
                <Col md={6}>
                  <Form.Floating className="mb-3">
                    <Form.Control type="email" name="email" placeholder="Email" required />
                    <label>Email</label>
                  </Form.Floating>
                </Col>
                <Col md={6}>
                  <Form.Floating className="mb-3">
                    <Form.Control type="tel" name="phone" placeholder="Phone" required />
                    <label>Phone</label>
                  </Form.Floating>
                </Col>
              </Row>

              <Form.Floating className="mb-3">
                <Form.Select name="subject" defaultValue="">
                  <option value="">Select a subject</option>
                  <option value="General">General Inquiry</option>
                  <option value="Support">Customer Support</option>
                  <option value="Partnership">Partnership</option>
                </Form.Select>
                <label>Subject</label>
              </Form.Floating>

              <Form.Floating className="mb-3">
                <Form.Control as="textarea" name="message" placeholder="Message" style={{ height: "120px" }} />
                <label>Message</label>
              </Form.Floating>

              <Button
                type="submit"
                className="w-100 d-flex align-items-center justify-content-center gap-2 send-btn"
                disabled={isSubmitting}
              >
                {isSubmitting ? (
                  <span className="custom-spinner"></span>
                ) : (
                  <>
                    <FaPaperPlane /> Send Message
                  </>
                )}
              </Button>

              {status && (
                <div
                  className={`mt-3 text-center fw-semibold ${
                    status.startsWith("✅") ? "text-success-msg" : "text-error-msg"
                  }`}
                >
                  {status}
                </div>
              )}
            </Form>
          </div>
        </Col>
      </Row>
    </Container>
  );
}
