import React, { useContext } from "react";
import { CartContext } from "../../context/CartContext";
import Explorer from "../../assets/Explorer.jpeg";
import "./ProductCard.css";

const products = [
  {
    id: 1,
    image: Explorer,
    title: "Curious Box",
    ageGroup: "For Ages 3-4 years",
    price: 1299,
    mrp: 1799,
    discount: 28,
    boxItems: [
      "Responsibility Chart",
      "My Calendar",
      "Alphabet Board",
      "Numbers Board",
      "Body Parts Board",
      "Stamp Art",
    ],
  },
  {
    id: 2,
    image: Explorer,
    title: "Explorer Box",
    ageGroup: "For Ages 4-6 years",
    price: 1399,
    mrp: 1999,
    discount: 30,
    boxItems: [
      "Tangram",
      "Mosaic",
      "Jumbo Jigsaw Puzzle",
      "Number Wheel",
      "Magic Books",
      "Crayons",
    ],
  },
];

const ProductCard = () => {
  const { cartItems, addToCart, decreaseQuantity } = useContext(CartContext);

  const getQuantity = (id) => {
    const item = cartItems.find((i) => i.id === id);
    return item ? item.quantity : 0;
  };

  return (
    <section className="product-section product py-5">
      <div className="container">
        <h2 className="section-heading text-center mb-5">
          Little Boxes, Big Adventures!
        </h2>
        <div className="row">
          {products.map((p) => {
            const quantity = getQuantity(p.id);

            return (
              <div className="col-md-6" key={p.id}>
                <div className="product-card p-4 mb-4 rounded shadow-sm">
                  <div className="row g-4 align-items-center">
                    {/* Left */}
                    <div className="col-md-6 text-center text-md-start">
                      <img
                        src={p.image}
                        alt={p.title}
                        className="img-fluid product-image mb-3"
                      />
                      <h4 className="product-title">{p.title}</h4>
                      <p className="product-age">{p.ageGroup}</p>
                      <div className="product-pricing d-flex align-items-center justify-content-center justify-content-md-start gap-2">
                        <span className="product-price">₹{p.price}</span>
                        <span className="product-mrp">₹{p.mrp}</span>
                        <span className="product-discount">{p.discount}% OFF</span>
                      </div>
                    </div>

                    {/* Right */}
                    <div className="col-md-6">
                      <h5 className="mb-3">What's in the box?</h5>
                      <ul className="list-unstyled product-box-items">
                        {p.boxItems.map((item, i) => (
                          <li key={i}>✔ {item}</li>
                        ))}
                      </ul>

                      {/* Add to Cart / Quantity Selector */}
                      <div className="mt-4 d-flex flex-wrap gap-3">
                        {quantity === 0 ? (
                          <button
                            className="btn btn-custom1"
                            onClick={() => addToCart(p)}
                          >
                            Add to Cart
                          </button>
                        ) : (
                          <div className="qty-selector d-flex align-items-center">
                            <button
                              className="qty-btn"
                              onClick={() => decreaseQuantity(p.id)}
                            >
                              -
                            </button>
                            <span className="mx-3">{quantity}</span>
                            <button
                              className="qty-btn"
                              onClick={() => addToCart(p)}
                            >
                              +
                            </button>
                          </div>
                        )}

                        {/* Dynamic Button */}
                        {quantity === 0 ? (
                          <button
                            className="btn btn-custom2"
                            onClick={() => {
                              addToCart(p);
                              window.location.href = "/cart";
                            }}
                          >
                            Buy Now
                          </button>
                        ) : (
                          <button
                            className="btn btn-custom2"
                            onClick={() => (window.location.href = "/cart")}
                          >
                            Go to Cart
                          </button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

export default ProductCard;
