import React, { useContext, useState } from "react";
import { useNavigate } from "react-router-dom";
import { CartContext } from "../context/CartContext";
import "./CheckoutPage.css";

const CheckoutItem = ({ item }) => {
  const totalMRP = item.mrp * item.quantity;
  const totalPrice = item.price * item.quantity;
  const discountPercent = Math.round(((item.mrp - item.price) / item.mrp) * 100);

  return (
    <div className="checkout-item">
      <div className="checkout-item-details">
        <img src={item.image} alt={item.title} className="checkout-product-img" />
        <div className="checkout-item-info">
          <span className="product-title">{item.title}</span>
          <span className="product-age">{item.ageGroup}</span>
          <span>Qty: {item.quantity}</span>
          <div className="product-pricing-inline">
            <span className="checkout-mrp">₹{totalMRP}</span>
            <span className="checkout-price">₹{totalPrice}</span>
            <span className="checkout-discount">{discountPercent}% OFF</span>
          </div>
        </div>
      </div>
      <hr className="product-divider" />
    </div>
  );
};

const CheckoutPage = () => {
  const {
    cartItems,
    saveShippingInfo,
    setOrder,
    cartSummary, // <-- updated context usage
  } = useContext(CartContext);

  const { subtotal, totalSavings, total, shipping } = cartSummary;

  const [childAge, setChildAge] = useState("");
  const [state, setState] = useState("");
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();

  const indianStates = [
    "Andhra Pradesh","Arunachal Pradesh","Assam","Bihar","Chhattisgarh",
    "Goa","Gujarat","Haryana","Himachal Pradesh","Jharkhand","Karnataka",
    "Kerala","Madhya Pradesh","Maharashtra","Manipur","Meghalaya",
    "Mizoram","Nagaland","Odisha","Punjab","Rajasthan","Sikkim",
    "Tamil Nadu","Telangana","Tripura","Uttar Pradesh","Uttarakhand",
    "West Bengal","Andaman and Nicobar Islands","Chandigarh",
    "Dadra and Nagar Haveli and Daman and Diu","Delhi","Jammu and Kashmir",
    "Ladakh","Lakshadweep","Puducherry"
  ];

  const handlePlaceOrder = (e) => {
    e.preventDefault();
    if (cartItems.length === 0) return alert("Cart is empty!");

    setLoading(true);

    // Get form data
    const formData = Object.fromEntries(new FormData(e.target).entries());

    // Include childAge even if empty
    formData.childAge = childAge || "N/A";

    saveShippingInfo(formData);

    setOrder({
      ...formData,
      cartItems,
      subtotal,
      totalSavings,
      shipping,
      total,
    });

    setLoading(false);
    // Redirect to Order Summary page
    navigate("/order-summary");
  };

  if (cartItems.length === 0) {
    return (
      <section className="checkout-page">
        <div className="container checkout-container">
          <p className="empty-cart">
            Your cart is empty. <a href="/shop">Go shopping</a>
          </p>
        </div>
      </section>
    );
  }

  return (
    <section className="checkout-page">
      <div className="container checkout-container">
        <div className="checkout-left">
          <form className="checkout-form" onSubmit={handlePlaceOrder}>
            <h4 className="checkout-heading">1. Shipping</h4>
            <div className="row g-3">
              <div className="col-md-6"><input type="text" name="firstName" placeholder="First Name" required /></div>
              <div className="col-md-6"><input type="text" name="lastName" placeholder="Last Name" required /></div>
              <div className="col-md-6">
                <input
                  type="number"
                  name="childAge"
                  placeholder="Child's Age (optional)"
                  min="1"
                  max="18"
                  value={childAge}
                  onChange={(e) => setChildAge(e.target.value)}
                />
              </div>
              <div className="col-md-6">
                <select name="state" value={state} onChange={(e) => setState(e.target.value)} required>
                  <option value="">Select State</option>
                  {indianStates.map((s, i) => <option key={i} value={s}>{s}</option>)}
                </select>
              </div>
              <div className="col-md-6"><input type="text" name="city" placeholder="City" required /></div>
              <div className="col-md-6"><input type="text" name="postalCode" placeholder="Postal Code" pattern="[0-9]{6}" maxLength="6" required /></div>
              <div className="col-md-12"><input type="text" name="streetAddress" placeholder="Street Address" required /></div>
            </div>

            <h4 className="checkout-heading">2. Contact Info</h4>
            <div className="row g-3">
              <div className="col-md-6"><input type="email" name="email" placeholder="Email" required /></div>
              <div className="col-md-6"><input type="tel" name="mobile" placeholder="10-digit mobile number" pattern="[0-9]{10}" maxLength="10" required /></div>
            </div>

            <button type="submit" className="btn-checkout" disabled={loading}>
              {loading ? "Placing Order..." : "Deliver Here"}
            </button>
          </form>
        </div>

        <div className="checkout-right">
          <div className="order-summary">
            <h5>Order Summary</h5>
            {cartItems.map((item) => <CheckoutItem key={item.id} item={item} />)}
            <div className="checkout-total"><span>Subtotal (MRP)</span><span>₹{subtotal}</span></div>
            {totalSavings > 0 && <div className="checkout-total text-success"><span>Total Savings</span><span>- ₹{totalSavings}</span></div>}
            <div className="checkout-total"><span>Shipping</span><span>₹{shipping}</span></div>
            <hr className="total-divider" />
            <div className="checkout-total fw-bold"><span>Total Payable</span><span>₹{total}</span></div>
            {totalSavings > 0 && <p className="checkout-savings">You will save ₹{totalSavings} on this order!</p>}
          </div>
        </div>
      </div>
    </section>
  );
};

export default CheckoutPage;
