import React, { createContext, useState, useEffect, useMemo, useCallback } from "react";

export const CartContext = createContext();

export const CartProvider = ({ children }) => {
  // --- State ---
  const [cartItems, setCartItems] = useState(() => {
    const saved = localStorage.getItem("cartItems");
    return saved ? JSON.parse(saved) : [];
  });

  const [discount, setDiscount] = useState(() => {
    const saved = localStorage.getItem("discount");
    return saved ? JSON.parse(saved) : 0;
  });

  const [promoCode, setPromoCode] = useState(() => localStorage.getItem("promoCode") || "");
  const [shippingInfo, setShippingInfo] = useState(() => {
    const saved = localStorage.getItem("shippingInfo");
    return saved ? JSON.parse(saved) : null;
  });
  const [order, setOrderState] = useState(() => {
    const saved = localStorage.getItem("order");
    return saved ? JSON.parse(saved) : null;
  });

  // --- Persist state ---
  useEffect(() => {
    localStorage.setItem("cartItems", JSON.stringify(cartItems));
  }, [cartItems]);

  useEffect(() => {
    localStorage.setItem("discount", JSON.stringify(discount));
  }, [discount]);

  useEffect(() => {
    localStorage.setItem("promoCode", promoCode);
  }, [promoCode]);

  useEffect(() => {
    localStorage.setItem("shippingInfo", JSON.stringify(shippingInfo));
  }, [shippingInfo]);

  useEffect(() => {
    if (order) localStorage.setItem("order", JSON.stringify(order));
  }, [order]);

  // --- Cart functions ---
  const addToCart = useCallback((product, qty = 1) => {
    if (qty <= 0) return;
    setCartItems((prev) => {
      const exist = prev.find((item) => item.id === product.id);
      if (exist)
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + qty } : item
        );
      return [...prev, { ...product, quantity: qty }];
    });
  }, []);

  const decreaseQuantity = useCallback((id) => {
    setCartItems((prev) =>
      prev
        .map((item) => (item.id === id ? { ...item, quantity: item.quantity - 1 } : item))
        .filter((item) => item.quantity > 0)
    );
  }, []);

  const removeFromCart = useCallback((id) =>
    setCartItems((prev) => prev.filter((item) => item.id !== id))
  , []);

  const updateQuantity = useCallback((id, qty) =>
    setCartItems((prev) =>
      prev.map((item) => (item.id === id ? { ...item, quantity: Math.max(1, qty) } : item))
    )
  , []);

  const clearCart = useCallback(() => {
    setCartItems([]);
    setDiscount(0);
    setPromoCode("");
    setShippingInfo(null);
    setOrderState(null);
    localStorage.removeItem("cartItems");
    localStorage.removeItem("discount");
    localStorage.removeItem("promoCode");
    localStorage.removeItem("shippingInfo");
    localStorage.removeItem("order");
  }, []);

  // --- Calculations (memoized for performance) ---
  const cartCount = useMemo(() => cartItems.reduce((sum, item) => sum + item.quantity, 0), [cartItems]);
  const subtotal = useMemo(() => cartItems.reduce((sum, item) => sum + item.mrp * item.quantity, 0), [cartItems]);
  const totalSavingsFromMRP = useMemo(
    () => cartItems.reduce((sum, item) => sum + (item.mrp - item.price) * item.quantity, 0),
    [cartItems]
  );
  const totalSavings = useMemo(() => totalSavingsFromMRP + discount, [totalSavingsFromMRP, discount]);

  // --- Shipping (same as before) ---
  const FREE_SHIPPING_THRESHOLD = 500;
  const shipping = subtotal - totalSavings >= FREE_SHIPPING_THRESHOLD ? 0 : 50;

  const total = useMemo(() => Math.max(0, subtotal - totalSavings + shipping), [subtotal, totalSavings, shipping]);

  // --- Promo code ---
  const PROMO_CODES = { SAVE100: 100, SAVE200: 200 };
  const applyPromoCode = useCallback((code) => {
    const trimmedCode = code.trim().toUpperCase();
    if (PROMO_CODES[trimmedCode]) {
      setDiscount(PROMO_CODES[trimmedCode]);
      setPromoCode(trimmedCode);
      return { success: true, message: `Promo code applied: ₹${PROMO_CODES[trimmedCode]} OFF` };
    }
    setDiscount(0);
    setPromoCode("");
    return { success: false, message: "Invalid promo code" };
  }, []);

  // --- Shipping info ---
  const saveShippingInfo = useCallback((info) => {
    setShippingInfo(info);
  }, []);

  // --- Generate Order ID ---
  const generateOrderId = () => {
    const prefix = "ORD";
    const timestamp = Date.now().toString().slice(-6);
    const randomNum = Math.floor(1000 + Math.random() * 9000);
    return `${prefix}-${timestamp}-${randomNum}`;
  };

  // --- Set Order ---
  const setOrder = useCallback((orderData) => {
    const orderWithId = {
      ...orderData,
      orderId: generateOrderId(),
      subtotal,
      totalSavings,
      shipping,
      total
    };
    setOrderState(orderWithId);
  }, [subtotal, totalSavings, shipping, total]);

  // --- Cart Summary Object for easy access ---
  const cartSummary = useMemo(() => ({
    cartCount,
    subtotal,
    totalSavings,
    shipping,
    total
  }), [cartCount, subtotal, totalSavings, shipping, total]);

  return (
    <CartContext.Provider
      value={{
        cartItems,
        addToCart,
        decreaseQuantity,
        removeFromCart,
        updateQuantity,
        clearCart,
        discount,
        promoCode,
        applyPromoCode,
        shippingInfo,
        saveShippingInfo,
        order,
        setOrder,
        cartSummary, // includes total amount
      }}
    >
      {children}
    </CartContext.Provider>
  );
};
