import React, { useContext, useState } from "react";
import { useNavigate } from "react-router-dom";
import { CartContext } from "../context/CartContext";
import './OrderSummary.css';

const OrderSummaryPage = () => {
  const { order } = useContext(CartContext);
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);

  if (!order) {
    return (
      <div className="container my-5 text-center">
        <h5>No order found!</h5>
        <a href="/shop" className="btn btn-warning mt-3">Go Shopping</a>
      </div>
    );
  }

  const handleConfirm = async () => {
    if (!order) return;
    setLoading(true);

    const endpoint = "https://script.google.com/macros/s/AKfycbz4FwiHtV6_BZcOsl9FTYIB03M4Gb-BRDkM0UxPAUtmw6hEbXMzEiIx6Ju-jEebV7FUDw/exec";

    try {
      await fetch(endpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        mode: "no-cors", 
        body: JSON.stringify({
          firstName: order.firstName,
          lastName: order.lastName,
          email: order.email,
          mobile: order.mobile,
          orderId: order.orderId,
          cartItems: order.cartItems.map(item => `${item.title} x${item.quantity}`).join(", "),
          subtotal: order.subtotal,
          totalSavings: order.totalSavings,
          shipping: order.shipping,
          total: order.total,
          streetAddress: order.streetAddress,
          city: order.city,
          state: order.state,
          postalCode: order.postalCode,
          childAge: order.childAge || "N/A",
          timestamp: new Date().toLocaleString(), // <-- added timestamp
        }),
      });

      navigate("/order-confirmation"); // redirect immediately
    } catch (err) {
      console.error("Failed to send order:", err);
      alert("Failed to submit order. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container my-5 mt-4">
      <div className="row justify-content-center">
        <div className="col-lg-8">

          <h4 className="text-center mb-5 mt-4 fw-bold">Order Summary</h4>

          {/* Order ID */}
          <div className="card summary-card mb-4">
            <div className="card-body">
              <h5 className="card-title">📦 Order ID</h5>
              <p className="mb-0">{order.orderId}</p>
            </div>
          </div>

          {/* Shipping Details */}
          <div className="card summary-card mb-4">
            <div className="card-body">
              <h5 className="card-title">🚚 Shipping Details</h5>
              <p className="mb-1"><strong>{order.firstName} {order.lastName}</strong></p>
              <p className="mb-1">{order.streetAddress}, {order.city}</p>
              <p className="mb-1">{order.state} - {order.postalCode}</p>
              {order.childAge && <p className="mb-1">Child's Age: {order.childAge}</p>}
            </div>
          </div>

          {/* Contact Info */}
          <div className="card summary-card mb-4">
            <div className="card-body">
              <h5 className="card-title">📞 Contact Info</h5>
              <p className="mb-1">📧 {order.email}</p>
              <p className="mb-1">📱 {order.mobile}</p>
            </div>
          </div>

          {/* Product Details */}
          <div className="card summary-card mb-4">
            <div className="card-body">
              <h5 className="card-title">🛍️ Products</h5>
              {order.cartItems.map(item => (
                <div key={item.id} className="d-flex align-items-center mb-3 product-item">
                  <img src={item.image} alt={item.title} className="rounded me-3 product-image" />
                  <div className="flex-grow-1">
                    <h6 className="mb-0">{item.title}</h6>
                    <small className="text-muted">{item.ageGroup}</small>
                    <div className="d-flex gap-2 mt-1 align-items-center">
                      <span className="product-price">₹{item.price}</span>
                      <span className="product-mrp">₹{item.mrp}</span>
                      {item.mrp > item.price && (
                        <span className="product-discount">{Math.round(((item.mrp - item.price)/item.mrp)*100)}% OFF</span>
                      )}
                      <span className="ms-auto">Qty: {item.quantity}</span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Price Summary */}
          <div className="card summary-card mb-4">
            <div className="card-body">
              <h5 className="card-title">💰 Price Details</h5>
              <div className="d-flex justify-content-between mb-1">
                <span>Subtotal (MRP)</span>
                <span>₹{order.subtotal}</span>
              </div>
              {order.totalSavings > 0 && (
                <div className="d-flex justify-content-between text-success mb-1">
                  <span>Total Savings</span>
                  <span>- ₹{order.totalSavings}</span>
                </div>
              )}
              <div className="d-flex justify-content-between mb-2">
                <span>Shipping</span>
                <span>₹{order.shipping}</span>
              </div>
              <hr />
              <div className="d-flex justify-content-between fw-bold total-payable">
                <span>Total Payable</span>
                <span>₹{order.total}</span>
              </div>
            </div>
          </div>

          {/* Confirm Button */}
          <div className="text-center">
            <button 
              className="btn btn-warning w-100 fw-bold py-2 confirm-btn" 
              onClick={handleConfirm}
              disabled={loading}
            >
              {loading ? "Submitting..." : "Confirm Order"}
            </button>
          </div>

        </div>
      </div>
    </div>
  );
};

export default OrderSummaryPage;
