import React, { useContext, useMemo, useCallback, useEffect } from "react";
import { Button } from "react-bootstrap";
import { CheckCircleFill } from "react-bootstrap-icons";
import confetti from "canvas-confetti";
import { motion } from "framer-motion";
import { CartContext } from "../context/CartContext";
import "./OrderConfirmation.css";

const OrderConfirmation = () => {
  const { order, clearCart } = useContext(CartContext);

  // Hooks are always called at the top
  const estimatedDeliveryDate = useMemo(() => {
    const today = new Date();
    const deliveryDate = new Date();
    deliveryDate.setDate(today.getDate() + 3);
    return deliveryDate.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
  }, []);

  const redirectToWhatsApp = useCallback(() => {
    if (!order) return;

    confetti({ particleCount: 100, spread: 120, origin: { y: 0.6 } });

    const WA_NUMBER = "917558004898";
    const customerName = `${order.firstName} ${order.lastName}`;
    const customerPhone = order.mobile || "N/A";
    const orderId = order.orderId;
    const itemsText = order.cartItems.map(item => `- ${item.title} x${item.quantity}`).join("\n");

    const message = encodeURIComponent(
      `🎉 *Order Summary* 🎉\n\n` +
      `Order ID: ${orderId}\n` +
      `Name: ${customerName}\n` +
      `Phone: ${customerPhone}\n` +
      `Estimated Delivery: ${estimatedDeliveryDate}\n\n` +
      `Items:\n${itemsText}\n\n` +
      `Thank you for shopping with us!`
    );

    window.open(`https://wa.me/${WA_NUMBER}?text=${message}`, "_blank", "noopener,noreferrer");
    clearCart();
    window.location.href = "/";
  }, [order, estimatedDeliveryDate, clearCart]);

  useEffect(() => {
    if (order) {
      confetti({ particleCount: 60, spread: 80, origin: { y: 0.6 } });
    }
  }, [order]);

  if (!order) {
    return (
      <div className="d-flex justify-content-center align-items-center vh-100">
        <p>Loading order details...</p>
      </div>
    );
  }

  const customerName = `${order.firstName} ${order.lastName}`;
  const customerPhone = order.mobile || "N/A";
  const orderId = order.orderId;

  return (
    <div className="order-confirmation-page">
      <div className="order-confirmation-container">
        <div className="card order-card text-center p-4 shadow-sm mx-auto" style={{ maxWidth: 500 }}>
          <motion.div
            className="mb-3 check-icon-wrapper"
            initial={{ scale: 0 }}
            animate={{ scale: 1 }}
            transition={{ type: "spring", stiffness: 300, damping: 20 }}
          >
            <CheckCircleFill size={60} className="check-icon" aria-label="Order successful" />
          </motion.div>

          <h2 className="fw-bold">Thank You for Your Order!</h2>
          <p className="text-muted mb-4">Your order summary is ready.</p>

          <section className="order-summary p-3 mb-3 border rounded shadow-sm bg-light text-start">
            <h5 className="fw-bold mb-2">Order Summary</h5>
            <p><strong>Order ID:</strong> <span className="text-primary">#{orderId}</span></p>
            <p><strong>Name:</strong> {customerName}</p>
            <p><strong>Phone:</strong> {customerPhone}</p>
            <p><strong>Estimated Delivery:</strong> {estimatedDeliveryDate}</p>

            <table className="table table-sm mt-2">
              <thead><tr><th>Item</th><th>Quantity</th></tr></thead>
              <tbody>
                {order.cartItems.length > 0 ? order.cartItems.map(item => (
                  <tr key={item.id}>
                    <td>{item.title}</td>
                    <td>{item.quantity}</td>
                  </tr>
                )) : <tr><td colSpan={2}>No items</td></tr>}
              </tbody>
            </table>

            {/* Payment Instructions Section */}
            <section className="payment-instructions my-3">
              💳 Payment instructions will be sent on WhatsApp! <br />
              Please complete UPI payment and share the screenshot.
            </section>
          </section>

          <Button
            style={{ backgroundColor: "#7851A9", borderColor: "#7851A9" }}
            className="mt-3 w-100"
            onClick={redirectToWhatsApp}
            aria-label="Redirect to WhatsApp for payment"
          >
            Open WhatsApp Now
          </Button>

          <p className="mt-4 text-muted">Thank you for shopping with us!</p>
        </div>
      </div>
    </div>
  );
};

export default OrderConfirmation;
