import React, { useContext, useState } from "react";
import { CartContext } from "../../context/CartContext";
import { FaTimes } from "react-icons/fa";
import { Link, useNavigate } from "react-router-dom";
import "./cart.css";

const CartPage = () => {
  const {
    cartItems,
    updateQuantity,
    removeFromCart,
    discount,
    applyPromoCode,
    cartSummary, // <-- new object
  } = useContext(CartContext);

  // Destructure totals from cartSummary
  const { subtotal, totalSavings, total } = cartSummary;

  const [promoCode, setPromoCode] = useState("");
  const [promoMsg, setPromoMsg] = useState(null);
  const navigate = useNavigate();

  const handleCheckout = () => {
    if (cartItems.length === 0) {
      alert("Cart is empty!");
      return;
    }
    navigate("/checkout");
  };

  const handleApplyPromo = () => {
    const result = applyPromoCode(promoCode.trim());
    setPromoMsg({
      type: result.success ? "success" : "error",
      msg: result.message,
    });
  };

  return (
    <section className="cart-page py-5 mt-3">
      <div className="container">
        <h2 className="cart-heading mb-4">Your Cart</h2>

        {/* Cart Header */}
        <div className="row cart-header py-2 border-bottom mb-2">
          <div className="col-5">Product</div>
          <div className="col-2">
            Price <br />
            <small>MRP / Off</small>
          </div>
          <div className="col-2">Quantity</div>
          <div className="col-2">Total</div>
          <div className="col-1"></div>
        </div>

        {/* Cart Items */}
        {cartItems.length === 0 ? (
          <p className="text-center mt-4">Your cart is empty!</p>
        ) : (
          cartItems.map((item) => (
            <div
              key={item.id}
              className="row align-items-center cart-item py-3 border-bottom"
            >
              <div className="col-5 d-flex align-items-center">
                <img
                  src={item.image}
                  alt={item.title}
                  className="cart-product-img me-2"
                />
                <div>
                  <h6 className="mb-1">{item.title}</h6>
                  <small>{item.ageGroup}</small>
                </div>
              </div>
              <div className="col-2">
                <span className="cart-price">₹{item.price}</span> <br />
                <small className="cart-mrp">₹{item.mrp}</small>{" "}
                <span className="cart-discount">{item.discount}% OFF</span>
              </div>
              <div className="col-2 d-flex align-items-center">
                <button
                  className="qty-btn"
                  onClick={() =>
                    updateQuantity(item.id, Math.max(item.quantity - 1, 1))
                  }
                >
                  -
                </button>
                <span className="mx-2">{item.quantity}</span>
                <button
                  className="qty-btn"
                  onClick={() => updateQuantity(item.id, item.quantity + 1)}
                >
                  +
                </button>
              </div>
              <div className="col-2">₹{item.price * item.quantity}</div>
              <div className="col-1">
                <FaTimes
                  className="remove-item"
                  onClick={() => removeFromCart(item.id)}
                />
              </div>
            </div>
          ))
        )}

        {/* Promo Code Section */}
        {cartItems.length > 0 && (
          <div className="promo-section mt-3">
            <h5>Have a Promo Code?</h5>
            <div className="promo-input-container mt-2">
              <input
                type="text"
                className="promo-input"
                placeholder="Enter promo code"
                value={promoCode}
                onChange={(e) => {
                  setPromoCode(e.target.value);
                  setPromoMsg(null);
                }}
              />
              <button className="btn-apply" onClick={handleApplyPromo}>
                Apply
              </button>
            </div>
            {promoMsg && (
              <p
                className={`promo-msg mt-2 ${
                  promoMsg.type === "success" ? "success" : "error"
                }`}
              >
                {promoMsg.msg}
              </p>
            )}
          </div>
        )}

        {/* Order Summary */}
        <div className="order-summary p-3 rounded shadow-sm mt-4">
          <h5>Order Summary</h5>
          <div className="d-flex justify-content-between mt-3">
            <span>Subtotal (MRP)</span>
            <span>₹{subtotal}</span>
          </div>
          {totalSavings > 0 && (
            <div className="d-flex justify-content-between text-success">
              <span>Total Savings</span>
              <span>- ₹{totalSavings}</span>
            </div>
          )}
          <hr />
          <div className="d-flex justify-content-between fw-bold">
            <span>Total Payable</span>
            <span>₹{total}</span>
          </div>

          {totalSavings > 0 && (
            <p className="savings-msg">
              You will save ₹{totalSavings} on this order!
            </p>
          )}

          <button
            className="btn btn-checkout w-100 mt-3"
            onClick={handleCheckout}
          >
            Checkout
          </button>
          <Link to="/shop" className="btn btn-continue mt-3">
            Continue Shopping
          </Link>
        </div>
      </div>
    </section>
  );
};

export default CartPage;
