import React, { useContext, useEffect, useState } from "react";
import { Link, useLocation } from "react-router-dom";
import "./NavBar.css";
import { CartContext } from "../../context/CartContext";

function NavBar() {
  const { cartItems } = useContext(CartContext);
  const totalItems = cartItems.reduce((sum, item) => sum + item.quantity, 0);

  const [animateCart, setAnimateCart] = useState(false);
  const [isCollapsed, setIsCollapsed] = useState(true);
  const location = useLocation();

  // Animate cart badge when totalItems changes
  useEffect(() => {
    if (totalItems > 0) {
      setAnimateCart(true);
      const timeout = setTimeout(() => setAnimateCart(false), 300);
      return () => clearTimeout(timeout);
    }
  }, [totalItems]);

  // Collapse menu when navigating
  useEffect(() => {
    setIsCollapsed(true);
  }, [location]);

  const toggleCollapse = () => {
    setIsCollapsed(!isCollapsed);
  };

  return (
    <nav className="navbar navbar-expand-lg fixed-top shadow-sm">
      <div className="container">
        <div className="underline-bar d-md-none"></div>

        {/* Logo */}
        <Link className="navbar-brand logo" to="/" aria-label="Home">
          Kidtivity
        </Link>

        {/* Cart + Hamburger wrapper */}
        <div className="d-flex align-items-center gap-3 order-md-3">
          {/* Cart icon for small screens */}
          <Link
            to="/cart"
            className="cart-icon position-relative d-md-none"
            aria-label="Cart"
          >
            <i className="fa-solid fa-bag-shopping"></i>
            {totalItems > 0 && (
              <span className={`cart-value ${animateCart ? "animate" : ""}`}>
                {totalItems}
              </span>
            )}
          </Link>

          {/* Hamburger button */}
          <button
            className="navbar-toggler"
            type="button"
            aria-controls="navbarMenu"
            aria-expanded={!isCollapsed}
            aria-label="Toggle navigation"
            onClick={toggleCollapse}
          >
            <span className="navbar-toggler-icon"></span>
          </button>
        </div>

        {/* Collapsible menu */}
        <div
          className={`collapse navbar-collapse ${!isCollapsed ? "show" : ""} order-md-2`}
          id="navbarMenu"
        >
          <ul className="navbar-nav mx-auto navlist">
            {[
              { name: "Home", path: "/" },
              { name: "Shop", path: "/shop" },
              { name: "Contact", path: "/contact" },
              { name: "About", path: "/about" },
            ].map((link) => (
              <li className="nav-item" key={link.name}>
                <Link
                  className={`nav-link ${location.pathname === link.path ? "active" : ""}`}
                  to={link.path}
                  onClick={() => setIsCollapsed(true)}
                >
                  {link.name}
                </Link>
              </li>
            ))}
          </ul>

          {/* Cart icon for medium+ screens */}
          <div className="d-none d-md-flex align-items-center gap-3 cart order-md-4">
            <Link to="/cart" className="cart-icon position-relative" aria-label="Cart">
              <i className="fa-solid fa-bag-shopping"></i>
              {totalItems > 0 && (
                <span className={`cart-value ${animateCart ? "animate" : ""}`}>
                  {totalItems}
                </span>
              )}
            </Link>
          </div>
        </div>
      </div>
    </nav>
  );
}

export default NavBar;
