import React, { useState } from "react";
import "./Faq.css";
import { FaChevronDown } from "react-icons/fa";
import faqImage from "../../assets/faq.png";

function Faq() {
  const [openIndex, setOpenIndex] = useState(null);
  const [page, setPage] = useState(0);
  const [userMessage, setUserMessage] = useState("");

  const faqs = [
    { q: "What is included in the box?", a: "Each box comes with fun and educational products tailored to your child’s age." },
    { q: "How fast is delivery?", a: "We deliver within 3–5 business days depending on location." },
    { q: "Can I customize my box?", a: "Yes, you can personalize your box during checkout." },
    { q: "What if I want to return?", a: "We offer hassle-free returns within 7 days." },
    { q: "Do you ship internationally?", a: "Currently we ship within the country only." },
    { q: "Is payment secure?", a: "Yes, all transactions are encrypted and completely safe." },
    { q: "Can I gift a box?", a: "Absolutely! Our boxes make wonderful gifts." },
    { q: "Is there a subscription option?", a: "Yes, you can subscribe monthly for surprise boxes." },
    { q: "What ages are boxes suitable for?", a: "We have boxes curated for ages 3–12." },
    { q: "How do I contact support?", a: "You can reach us via WhatsApp or email anytime." },
    { q: "Do you offer discounts?", a: "We provide seasonal offers and bundle discounts." },
    { q: "What’s inside a learning box?", a: "It includes toys, puzzles, and books to boost creativity." }
  ];

  const faqsPerPage = 8;
  const startIndex = page * faqsPerPage;
  const displayedFaqs = faqs.slice(startIndex, startIndex + faqsPerPage);

  const toggleFaq = (idx) => setOpenIndex(openIndex === idx ? null : idx);

  // WhatsApp link with newline before user message
  const whatsappLink = `https://wa.me/+917558004898?text=${encodeURIComponent(
    `Hello! I have a question about your boxes:\n${userMessage || ""}`
  )}`;

  const handleKeyPress = (e) => {
    if (e.key === "Enter" && userMessage.trim()) {
      window.open(whatsappLink, "_blank");
    }
  };

  return (
    <section className="faq-section py-5">
      <div className="container">

        {/* Main heading centered */}
        <div className="text-center mb-4">
          <h2 className="faq-title">Frequently Asked Question</h2>
          <p className="faq-subtitle">Everything you need to know before unboxing the fun.</p>
        </div>

        <div className="row d-flex align-items-stretch">
          {/* LEFT SIDE */}
          <div className="col-md-6 d-flex flex-column left">
            <div className="faq-image-wrapper flex-grow-1">
              <img src={faqImage} alt="FAQ" className="faq-image" />
            </div>

            <h4 className="mt-2 mb-1 input-heading">Didn't find your answer?</h4>
            <p className="faq-subhead mb-2 input-subhead">
              Type your question below and we'll help you instantly on WhatsApp.
            </p>

            <label
              htmlFor="questionInput"
              className="form-label fw-bold mb-1 input-heading"
            >
              Let us Know
            </label>
            <input
              type="text"
              id="questionInput"
              className="form-control mb-2"
              placeholder="Enter Here"
              value={userMessage}
              onChange={(e) => setUserMessage(e.target.value)}
              onKeyDown={handleKeyPress}
            />

            <div className="text-center mt-2">
              <a
                href={userMessage.trim() ? whatsappLink : undefined}
                target="_blank"
                rel="noopener noreferrer"
                className={`btn faq-send-btn px-4 ${!userMessage.trim() ? "disabled" : ""}`}
                onClick={(e) => {
                  if (!userMessage.trim()) e.preventDefault();
                }}
              >
                Send
              </a>
            </div>
          </div>

          {/* RIGHT SIDE */}
          <div className="col-md-6 d-flex flex-column mt-4 mt-md-0">
            <div className="flex-grow-1">
              {displayedFaqs.map((item, idx) => (
                <div
                  key={item.q}
                  className="card mb-2 shadow-sm faq-card"
                >
                  <button
                    className="card-body d-flex justify-content-between align-items-center faq-btn"
                    onClick={() => toggleFaq(idx)}
                    aria-expanded={openIndex === idx}
                  >
                    <span className={`faq-question ${openIndex === idx ? "active" : ""}`}>
                      {item.q}
                    </span>
                    <FaChevronDown
                      className={`faq-icon ${openIndex === idx ? "rotated" : ""}`}
                    />
                  </button>
                  <div
                    className={`faq-answer ${openIndex === idx ? "open" : ""}`}
                  >
                    <p className="mb-0">{item.a}</p>
                  </div>
                </div>
              ))}
            </div>

            {/* Pagination */}
            <div className="d-flex flex-column align-items-center mt-3">
              <div className="d-flex justify-content-center gap-3">
                <button
                  className="faq-nav-btn"
                  onClick={() => setPage(page - 1)}
                  disabled={page === 0}
                >
                  ‹
                </button>
                <button
                  className="faq-nav-btn"
                  onClick={() => setPage(page + 1)}
                  disabled={startIndex + faqsPerPage >= faqs.length}
                >
                  ›
                </button>
              </div>
              <p className="mt-2 page-indicator">
                 {page + 1} of {Math.ceil(faqs.length / faqsPerPage)}
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default Faq;



